import { sql } from 'drizzle-orm';
import {
  boolean,
  date,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

/** Time-sortable UUIDv7 generated by Postgres 18. */
const pk = () => uuid('id').primaryKey().default(sql`uuidv7()`);
const ts = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });
const createdAt = () => ts('created_at').notNull().defaultNow();

// ───────────────────────── Auth.js tables (shape required by @auth/drizzle-adapter) ─────────────────────────
export const users = pgTable('users', {
  id: uuid('id').primaryKey().default(sql`uuidv7()`),
  name: text('name'),
  email: text('email').unique(),
  emailVerified: ts('email_verified'),
  image: text('image'),
  // Arena OS profile fields
  dateOfBirth: date('date_of_birth', { mode: 'string' }),
  timezone: text('timezone').notNull().default('UTC'),
  onboardedAt: ts('onboarded_at'),
  createdAt: createdAt(),
});

export const accounts = pgTable(
  'accounts',
  {
    userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
    type: text('type').notNull(),
    provider: text('provider').notNull(),
    providerAccountId: text('provider_account_id').notNull(),
    refresh_token: text('refresh_token'),
    access_token: text('access_token'),
    expires_at: integer('expires_at'),
    token_type: text('token_type'),
    scope: text('scope'),
    id_token: text('id_token'),
    session_state: text('session_state'),
  },
  (t) => [primaryKey({ columns: [t.provider, t.providerAccountId] })],
);

export const sessions = pgTable('sessions', {
  sessionToken: text('session_token').primaryKey(),
  userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  expires: ts('expires').notNull(),
});

export const verificationTokens = pgTable(
  'verification_tokens',
  {
    identifier: text('identifier').notNull(),
    token: text('token').notNull(),
    expires: ts('expires').notNull(),
  },
  (t) => [primaryKey({ columns: [t.identifier, t.token] })],
);

// ───────────────────────── Tenancy ─────────────────────────
export const organizations = pgTable('organizations', {
  id: pk(),
  name: text('name').notNull(),
  slug: text('slug').notNull().unique(),
  /** Seeded demo orgs. The UI shows a persistent "DEMO DATA" badge. */
  isDemo: boolean('is_demo').notNull().default(false),
  createdBy: uuid('created_by').references(() => users.id),
  createdAt: createdAt(),
  deletedAt: ts('deleted_at'),
});

export const memberships = pgTable(
  'memberships',
  {
    id: pk(),
    orgId: uuid('org_id').notNull().references(() => organizations.id, { onDelete: 'cascade' }),
    userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
    /** owner | manager | member | guest. `member` defers to the per-team role. */
    role: text('role').notNull(),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex('memberships_org_user').on(t.orgId, t.userId), index('memberships_user').on(t.userId)],
);

export const teams = pgTable(
  'teams',
  {
    id: pk(),
    orgId: uuid('org_id').notNull().references(() => organizations.id, { onDelete: 'cascade' }),
    /** Game module id (string, validated against the generated registry; never a DB enum). */
    gameId: text('game_id').notNull(),
    edition: text('edition'),
    name: text('name').notNull(),
    slug: text('slug').notNull(),
    createdAt: createdAt(),
    deletedAt: ts('deleted_at'),
  },
  (t) => [uniqueIndex('teams_org_slug').on(t.orgId, t.slug)],
);

export const teamMemberships = pgTable(
  'team_memberships',
  {
    id: pk(),
    orgId: uuid('org_id').notNull().references(() => organizations.id, { onDelete: 'cascade' }),
    teamId: uuid('team_id').notNull().references(() => teams.id, { onDelete: 'cascade' }),
    userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
    /** coach | analyst | player | staff */
    role: text('role').notNull(),
    /** In-game role id from the Game Module (e.g. "duelist"). */
    gameRoleId: text('game_role_id'),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex('team_memberships_team_user').on(t.teamId, t.userId), index('team_memberships_user').on(t.userId)],
);

export const invites = pgTable(
  'invites',
  {
    id: pk(),
    orgId: uuid('org_id').notNull().references(() => organizations.id, { onDelete: 'cascade' }),
    email: text('email').notNull(),
    orgRole: text('org_role').notNull(),
    teamId: uuid('team_id').references(() => teams.id, { onDelete: 'cascade' }),
    teamRole: text('team_role'),
    /** SHA-256 of the emailed token. The raw token is never stored. */
    tokenHash: text('token_hash').notNull().unique(),
    invitedBy: uuid('invited_by').notNull().references(() => users.id),
    expiresAt: ts('expires_at').notNull(),
    acceptedAt: ts('accepted_at'),
    acceptedBy: uuid('accepted_by').references(() => users.id),
    revokedAt: ts('revoked_at'),
    createdAt: createdAt(),
  },
  (t) => [index('invites_org').on(t.orgId)],
);

// ───────────────────────── Audit, consent, grants ─────────────────────────
/** Append-only (the runtime role has no UPDATE/DELETE) and hash-chained per org. */
export const auditLog = pgTable(
  'audit_log',
  {
    id: pk(),
    orgId: uuid('org_id').notNull().references(() => organizations.id, { onDelete: 'cascade' }),
    actorUserId: uuid('actor_user_id'),
    action: text('action').notNull(),
    resourceType: text('resource_type').notNull(),
    resourceId: text('resource_id'),
    /** Owner-only actions are hidden from managers (see authz `ownerAction`). */
    ownerAction: boolean('owner_action').notNull().default(false),
    metadata: jsonb('metadata').$type<Record<string, unknown>>().notNull().default({}),
    ip: text('ip'),
    userAgent: text('user_agent'),
    prevHash: text('prev_hash'),
    hash: text('hash').notNull(),
    createdAt: ts('created_at').notNull(),
  },
  (t) => [index('audit_org_created').on(t.orgId, t.createdAt)],
);

export const consentRecords = pgTable(
  'consent_records',
  {
    id: pk(),
    userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
    /** e.g. terms, privacy, voice_recording, wellness_processing */
    purpose: text('purpose').notNull(),
    version: text('version').notNull(),
    granted: boolean('granted').notNull(),
    createdAt: createdAt(),
  },
  (t) => [index('consent_user').on(t.userId)],
);

export const guardianConsents = pgTable('guardian_consents', {
  id: pk(),
  playerUserId: uuid('player_user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  guardianName: text('guardian_name').notNull(),
  guardianEmail: text('guardian_email').notNull(),
  tokenHash: text('token_hash').notNull().unique(),
  requestedAt: createdAt(),
  expiresAt: ts('expires_at').notNull(),
  verifiedAt: ts('verified_at'),
  revokedAt: ts('revoked_at'),
});

/** Explicit, revocable, expiring access grants (e.g. a player lets a coach read their wellness data). */
export const permissionGrants = pgTable(
  'permission_grants',
  {
    id: pk(),
    orgId: uuid('org_id').notNull().references(() => organizations.id, { onDelete: 'cascade' }),
    grantorUserId: uuid('grantor_user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
    granteeUserId: uuid('grantee_user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
    scope: text('scope').notNull(),
    expiresAt: ts('expires_at').notNull(),
    revokedAt: ts('revoked_at'),
    createdAt: createdAt(),
  },
  (t) => [index('grants_org_grantee').on(t.orgId, t.granteeUserId)],
);

export type User = typeof users.$inferSelect;
export type Organization = typeof organizations.$inferSelect;
export type Membership = typeof memberships.$inferSelect;
export type Team = typeof teams.$inferSelect;
export type TeamMembership = typeof teamMemberships.$inferSelect;
export type Invite = typeof invites.$inferSelect;
export type AuditLogRow = typeof auditLog.$inferSelect;
